// story-example.workflow.js — example generated story-runner workflow.
// This file is a concrete instance of the story-runner.template.js, with
// placeholder tokens filled for a realistic story.
// Scenario: myproject:backlog:1 — 'Bootstrap DB schema' story, finalize with PR.
// Generated by: loom:writing-workflows
//
// Phases:
//   Execute / Validate / Fix — convergence loop (prepare)
//   Finalize                 — final validation, then open a PR (default) or
//                              merge + push to main

export const meta = {
  name: 'story-runner',
  description: 'Single-story runner: build → validate convergence loop (with inline story-fixer), then finalize (open a PR by default, or merge + push to main when requested)',
  phases: [
    { title: 'Execute',  detail: 'story-executor builds the story branch' },
    { title: 'Validate', detail: 'story-validator checks criteria and tests' },
    { title: 'Fix',      detail: 'story-fixer applies validator failures inline' },
    { title: 'Finalize', detail: 'final validation, then open a PR (default) or merge + push to main' },
  ],
}

// ── Schema constants ─────────────────────────────────────────────────────────
// EXECUTOR_SCHEMA  — story-executor (loom:story-executor) result
// VALIDATOR_SCHEMA — story-validator result
// FIXER_SCHEMA     — story-fixer and code-hygiene agent result
// MERGE_SCHEMA     — finalize-merge agent result
// PR_SCHEMA        — finalize-pr agent result

const EXECUTOR_SCHEMA = {
  type: 'object',
  required: ['story_qid', 'branch', 'worktree'],
  properties: {
    story_qid: { type: 'string' },
    branch:    { type: 'string' },
    worktree:  { type: 'string' },
    notes:     { type: 'string' },
  },
}

const VALIDATOR_SCHEMA = {
  type: 'object',
  required: ['result', 'criteria'],
  properties: {
    result:   { type: 'string', enum: ['ok', 'failed'] },
    criteria: {
      type: 'array',
      items: {
        type: 'object',
        required: ['text', 'pass', 'evidence'],
        properties: {
          text:     { type: 'string' },
          pass:     { type: 'boolean' },
          evidence: { type: 'string' },
        },
      },
    },
  },
}

const FIXER_SCHEMA = {
  type: 'object',
  required: ['summary'],
  properties: {
    summary: { type: 'string' },
  },
}


const MERGE_SCHEMA = {
  type: 'object',
  required: ['merged'],
  properties: {
    merged:    { type: 'boolean' },
    merge_sha: { type: ['string', 'null'] },
    conflict:  { type: 'string' },
  },
}

const PR_SCHEMA = {
  type: 'object',
  required: ['pr_url'],
  properties: { pr_url: { type: ['string', 'null'] } },
}

// ── Inputs ───────────────────────────────────────────────────────────────────
// Tokens below are replaced at bake time; they are valid JS string literals.

const STORY_QID = 'myproject:backlog:1'
const FINALIZE = 'pr'

// ── Helpers ──────────────────────────────────────────────────────────────────

// prepare(qid, parentBranch) — execute → validate convergence loop (≤3 attempts).
// Attempt 1: story-executor builds the branch. Subsequent attempts: story-fixer
// applies the failed criteria from the previous validate step. Steps are tagged
// via opts.phase (NOT phase()) so the loop is safe to run concurrently.
// Returns { qid, executor, ok, open, attempts }:
//   ok:       true if the story converged
//   executor: the executor result (kept from attempt 1)
//   open:     array of unmet criterion texts (non-empty only when ok=false)
//   attempts: number of attempts made
async function prepare(qid, parentBranch) {
  const MAX_ATTEMPTS = 3
  let attempt = 0
  let executor = null
  let open = []

  while (attempt < MAX_ATTEMPTS) {
    attempt++
    log(`[${qid}] prepare attempt ${attempt}/${MAX_ATTEMPTS}`)

    if (attempt === 1) {
      // Execute: story-executor builds the story branch.
      executor = await agent(
        `story_qid=${qid} parent_branch=${parentBranch}`,
        { label: `executor:${qid}:${attempt}`, phase: 'Execute', agentType: 'loom:story-executor', schema: EXECUTOR_SCHEMA }
      )
      log(`[${qid}] executor done: branch=${executor.branch}`)
    } else {
      // Fix: story-fixer resumes the existing worktree and applies the failed criteria.
      const failedLines = open.join('\n')
      await agent(
        `story_qid=${qid} branch=${executor.branch} worktree=${executor.worktree}\nfailed_criteria:\n${failedLines}`,
        { label: `fixer:${qid}:${attempt}`, phase: 'Fix', agentType: 'loom:story-fixer', schema: FIXER_SCHEMA }
      )
      log(`[${qid}] fixer done (attempt ${attempt})`)
    }

    // Validate: story-validator checks criteria and tests.
    const validate = await agent(
      `story_qid=${qid} branch=${executor.branch} worktree=${executor.worktree}`,
      { label: `validator:${qid}:${attempt}`, phase: 'Validate', agentType: 'loom:story-validator', schema: VALIDATOR_SCHEMA }
    )

    if (validate.result === 'ok') {
      return { qid, executor, ok: true, open: [], attempts: attempt }
    }

    open = validate.criteria.filter(c => !c.pass).map(c => c.text)
    log(`[${qid}] validation failed: ${open.length} unmet criterion(a)`)
  }

  log(`[${qid}] did not converge after ${MAX_ATTEMPTS} attempts`)
  return { qid, executor, ok: false, open, attempts: MAX_ATTEMPTS }
}

// ── Convergence ──────────────────────────────────────────────────────────────

log(`Running story ${STORY_QID} (finalize=${FINALIZE})`)

const result = await prepare(STORY_QID, 'main')

if (!result.ok) {
  return {
    result: 'failed',
    story_qid: STORY_QID,
    attempts: result.attempts,
    reason: result.open.join('; '),
  }
}

const { executor } = result
const attempts = result.attempts

// ── Hygiene pass ─────────────────────────────────────────────────────────────

// Run code-hygiene over the story branch before the final validation gate.
// Hygiene edits land on the branch and are then verified by story-validator.
log('Running code-hygiene pass before final validation')
await agent(
  `branch=${executor.branch} worktree=${executor.worktree} trunk=main`,
  { label: 'code-hygiene', phase: 'Validate', agentType: 'loom:code-hygiene', schema: FIXER_SCHEMA }
)

// ── Finalize ─────────────────────────────────────────────────────────────────

// Final gate before main (the single-story analog of the epic's epic-validator
// phase): re-validate the branch, mark the story done, then merge or open a PR.
log('Running final story-validator before finalize')
const finalValidation = await agent(
  `story_qid=${STORY_QID} branch=${executor.branch} worktree=${executor.worktree}`,
  { label: 'final-validator', phase: 'Validate', agentType: 'loom:story-validator', schema: VALIDATOR_SCHEMA }
)
if (finalValidation.result !== 'ok') {
  const unmet = finalValidation.criteria.filter(c => !c.pass).map(c => c.text).join('; ')
  return { result: 'failed', story_qid: STORY_QID, attempts, reason: `final-validation: ${unmet}` }
}

// Mark the story done in loom.
await agent(
  `Run: loom complete ${STORY_QID}`,
  { label: `complete-story:${STORY_QID}`, phase: 'Finalize', agentType: 'loom:story-executor' }
)

if (FINALIZE === 'merge') {
  // Merge + push into main (only when explicitly requested).
  log(`Merging ${executor.branch} into main and pushing`)
  const merge = await agent(
    `Finalize the story by merging the story branch into main and pushing.
Run from the repo root (NOT the story worktree):
1. git checkout main && git fetch origin && git pull --ff-only origin main
2. git merge --no-ff ${executor.branch} -m "Merge ${executor.branch}: story ${STORY_QID}"

If step 2 conflicts: resolve ONLY trivial, unambiguous conflicts (non-overlapping
added lines, lockfile/index unions, whitespace). If a conflict touches real logic
or there is ANY chance the correct resolution depends on intent, run
"git merge --abort" and return { "merged": false, "conflict": "<files and why>" }
— do NOT push.

On a clean (or trivially-resolved) merge:
3. git push origin main
4. git rev-parse HEAD   (record as merge_sha)
5. git branch -d ${executor.branch}
6. git worktree remove --force ${executor.worktree}
Return { "merged": true, "merge_sha": "<sha>" }.`,
    { label: 'finalize-merge', phase: 'Finalize', schema: MERGE_SCHEMA }
  )
  if (!merge.merged) {
    return { result: 'failed', story_qid: STORY_QID, attempts, reason: `merge conflict: ${merge.conflict}` }
  }
  log(`Merged ${executor.branch} into main at ${merge.merge_sha}.`)
  return { result: 'ok', story_qid: STORY_QID, branch: executor.branch, merged_to: 'main', attempts }
} else {
  // Default: push branch + open PR.
  log(`Pushing ${executor.branch} and opening PR`)
  const pr = await agent(
    `Finalize the story by pushing the branch and opening a pull request.
1. cd ${executor.worktree}
2. git push -u origin ${executor.branch}
3. Compose a coherent PR body — do NOT use a generic "automated PR" string. Read
   the story for intent (loom show ${STORY_QID} --json) and the diff for what shipped:
     git diff main...${executor.branch} --stat
     git log main..${executor.branch} --oneline
   Write a short Markdown body: a one-paragraph summary + a "## Changes" bullet
   list grounded in the diff. Every claim must match a real change.
4. gh pr create --base main --head ${executor.branch} --title "Story ${STORY_QID}: <short summary>" --body-file <tmpfile> and capture the URL
Return { "pr_url": "<url>" }.`,
    { label: 'finalize-pr', phase: 'Finalize', schema: PR_SCHEMA }
  )
  log(`Finalized. PR URL: ${pr.pr_url ?? '(none)'}`)
  return { result: 'ok', story_qid: STORY_QID, branch: executor.branch, pr_url: pr.pr_url, attempts }
}
